import sys, optparse, json

FILEHEADER = """
/* DO NOT EDIT! This is an autogenerated file. See scripts/litex/parse_csr.py */
"""

# Required cores and the local prefix names to use
RequiredCores = {
    "UART": "UART",
    "Timer": "TIMER",
}

# Required constants to extract
RequiredConstants = [
    "config_clock_frequency"
]

# Constants to verify are present
VerifyConstants = {
    "config_cpu_has_interrupt": None,
    "config_cpu_family": "riscv",
    "config_csr_data_width": 32,
    "config_csr_ordering_little": None,
}

def error(msg):
    sys.stderr.write("Litex build error!\n%s\n" % (msg,))
    sys.exit(-1)

def find_cores(csr, core_type, req_regs=None):
    out = []
    for cname, ctype in csr['cores'].items():
        if ctype != core_type:
            continue
        if req_regs is not None:
            f = [(cname + "_" + r) in csr['csr_registers'] for r in req_regs]
            if not all(f):
                continue
        out.append(cname)
    return out

def find_core(csr, core_type):
    out = find_cores(csr, core_type)
    if not out:
        error("Unable to find core type '%s'" % (core_type,))
    if len(out) != 1:
        error("More than one core type '%s' found" % (core_type,))
    return out[0]

def build_csr_registers(csr, local_name, cname):
    out = []
    prefix = cname + "_"
    for reg_name, reg_info in csr['csr_registers'].items():
        if not reg_name.startswith(prefix):
            continue
        def_name = "LREG_%s_%s" % (local_name, reg_name[len(prefix):])
        out.append("#define %s ((void*)0x%08x)" % (def_name, reg_info['addr']))
    return out

def build_constant(csr, const_name, local_name=None):
    if local_name is None:
        local_name = const_name
    if const_name not in csr['constants']:
        error("Unable to find constant '%s'" % (const_name,))
    value = csr['constants'][const_name]
    def_name = "LDEF_%s" % (local_name,)
    return ["#define %s %s" % (def_name, value)]

def verify_constant(csr, const_name, expected_value):
    if const_name not in csr['constants']:
        error("Unable to find required constant '%s'" % (const_name,))
    if (expected_value is not None
        and expected_value != csr['constants'][const_name]):
        error("Expected required constant '%s' with value '%s'"
              % (const_name, expected_value))

def build_mem_def(csr, local_name, seg_name):
    seg_info = csr['memories'].get(seg_name)
    if seg_info is None:
        error("Unable to find memory segment '%s'" % (seg_name,))
    def_addr_name = "LMEM_ADDR_%s" % (local_name,)
    def_size_name = "LMEM_SIZE_%s" % (local_name,)
    return ["#define %s 0x%08x" % (def_addr_name, seg_info['base']),
            "#define %s 0x%08x" % (def_size_name, seg_info['size'])]

def build_gpio(csr):
    def fmt_addr(reg_info):
        return '(void*)0x%08x' % (reg_info['addr'],)
    gpios = {}
    # LEDs and GPIOOut
    cores = find_cores(csr, "LedChaser", ["out"])
    cores += find_cores(csr, "GPIOOut", ["out"])
    for core in cores:
        pinname = core + ".0"
        out_reg = csr['csr_registers'][core+"_out"]
        gpios[pinname] = {'out': fmt_addr(out_reg)}
    # GPIOIn
    cores = find_cores(csr, "GPIOIn", ["in"])
    for core in cores:
        pinname = core + ".0"
        in_reg = csr['csr_registers'][core+"_in"]
        gpios[pinname] = {'in': fmt_addr(in_reg)}
    # GPIOTristate
    cores = find_cores(csr, "GPIOTristate", ["in", "out", "oe"])
    for core in cores:
        pinname = core + ".0"
        in_reg = csr['csr_registers'][core+"_in"]
        out_reg = csr['csr_registers'][core+"_out"]
        oe_reg = csr['csr_registers'][core+"_oe"]
        gpios[pinname] = {'in': fmt_addr(in_reg),
                          'out': fmt_addr(out_reg), 'oe': fmt_addr(oe_reg)}
    # Generate output
    pinnames = list(sorted(gpios.keys()))
    out = [FILEHEADER]
    for i, pinname in enumerate(pinnames):
        out.append('DECL_ENUMERATION_RANGE("pin", "%s", GPIO(%d, 0), 32);'
                   % (pinname, i))
    out.append("struct gpiodef digital_regs[] = {")
    for pinname in pinnames:
        fields = [".%s=%s" % (f, v) for f, v in gpios[pinname].items()]
        out.append("{ %s }," % (", ".join(fields)))
    out.append("};")
    return out

def process(csr, options):
    out = [FILEHEADER]
    # Output register addresses and interrupt defs for desired cores
    for core_type, local_name in RequiredCores.items():
        cname = find_core(csr, core_type)
        lines = build_csr_registers(csr, local_name, cname)
        out.extend(lines)
        lines = build_constant(csr, cname+"_interrupt", local_name+"_interrupt")
        out.extend(lines)
    # Output required constants
    for const_name in RequiredConstants:
        lines = build_constant(csr, const_name)
        out.extend(lines)
    # Verify required constants are present
    for const_name, expected_value in VerifyConstants.items():
        verify_constant(csr, const_name, expected_value)
    # Output memory locations
    lines = build_mem_def(csr, "CODE", options.ram_code)
    out.extend(lines)
    lines = build_mem_def(csr, "RAM", options.ram)
    out.extend(lines)
    # Output gpio definitions
    gpiolines = build_gpio(csr)
    return "\n".join(out), "\n".join(gpiolines)

def main():
    # Parse program args
    usage = "%prog [options]"
    opts = optparse.OptionParser(usage)
    opts.add_option("-i", "--input", dest="input_csr",
                    help="input csr.json file to parse")
    opts.add_option("-o", "--output-defs", dest="output_defs",
                    help="output C header file")
    opts.add_option("-g", "--output-gpio", dest="output_gpio",
                    help="output C gpio definition file")
    opts.add_option("-r", "--ram", dest="ram",
                    default='sram',
                    help="name of ram segment used for variables")
    opts.add_option("-c", "--ram-code", dest="ram_code",
                    default='main_ram',
                    help="name of ram segment to hold code")
    options, args = opts.parse_args()
    if len(args):
        opts.error("Incorrect number of arguments")
    if options.input_csr is None or options.output_defs is None:
        opts.error("Must specify both -i and -o options")

    # Read input file contents
    f = open(options.input_csr, "r")
    fdata = f.read()
    f.close()
    csr = json.loads(fdata)

    # Process definitions
    outdata, outgpio = process(csr, options)

    # Write output
    old_data = old_gpio = None
    try:
        f = open(options.output_defs, "r")
        old_data = f.read()
        f.close()
        if options.output_gpio is not None:
            f = open(options.output_gpio, "r")
            old_gpio = f.read()
            f.close()
    except:
        pass
    if outdata != old_data:
        f = open(options.output_defs, "w")
        f.write(outdata)
        f.close()
    if options.output_gpio is not None and outgpio != old_gpio:
        f = open(options.output_gpio, "w")
        f.write(outgpio)
        f.close()

if __name__ == '__main__':
    main()
